import numpy as np
from PIL import Image
from scipy import ndimage
from scipy.sparse import coo_matrix
from scipy.sparse.csgraph import dijkstra
im=np.asarray(Image.open('/app/target.png').convert('L')); m=im<80
# zhang suen
s=m.copy();
while True:
 changed=0
 p=np.pad(s,1); nb=np.stack([p[:-2,1:-1],p[:-2,2:],p[1:-1,2:],p[2:,2:],p[2:,1:-1],p[2:,:-2],p[1:-1,:-2],p[:-2,:-2]])
 c=nb.sum(0); tr=sum((~nb[j]&nb[(j+1)%8]) for j in range(8))
 for a,b in [(np.array([0,2,4]),np.array([2,4,6])),(np.array([0,2,6]),np.array([0,4,6]))]:
  rem=s&(c>=2)&(c<=6)&(tr==1)&(nb[a].all(0)==False)&(nb[b].all(0)==False)
  changed+=int(rem.sum());s[rem]=0
  p=np.pad(s,1);nb=np.stack([p[:-2,1:-1],p[:-2,2:],p[1:-1,2:],p[2:,2:],p[2:,1:-1],p[2:,:-2],p[1:-1,:-2],p[:-2,:-2]]);c=nb.sum(0);tr=sum((~nb[j]&nb[(j+1)%8]) for j in range(8))
 if changed==0:break
labels,n=ndimage.label(s,np.ones((3,3),bool));print('skeleton comps',[(i,int((labels==i).sum())) for i in range(1,n+1)])
for ci in range(1,n+1):
 yy,xx=np.where(labels==ci); lookup={(y,x):i for i,(y,x) in enumerate(zip(yy,xx))}; rows=[];cols=[];weights=[]
 for i,(y,x) in enumerate(zip(yy,xx)):
  for dy,dx,w in [(a,b,1.41421356 if a and b else 1.) for a in (-1,0,1) for b in (-1,0,1) if (a,b)!=(0,0)]:
   j=lookup.get((y+dy,x+dx))
   if j is not None: rows.append(i);cols.append(j);weights.append(w)
 g=coo_matrix((weights,(rows,cols)),shape=(len(xx),len(xx))).tocsr(); deg=np.diff(g.indptr); ends=np.where(deg==1)[0]
 print('\nCI',ci,'N',len(xx),'endpoints',[(int(xx[e]),int(yy[e])) for e in ends])
 if len(ends):
  ds,pr=dijkstra(g,directed=False,indices=ends,return_predecessors=True)
  best=(-1,None,None)
  for i in range(len(ends)):
   for j in range(i+1,len(ends)):
    if ds[i,ends[j]]>best[0]:best=(ds[i,ends[j]],i,j)
  print('longest endpoint pair',best[0],(int(xx[ends[best[1]]]),int(yy[ends[best[1]]])),(int(xx[ends[best[2]]]),int(yy[ends[best[2]]])))
  i,j=best[1:];cur=ends[j];path=[cur]
  while cur!=ends[i] and len(path)<10000:
   cur=pr[i,cur]
   if cur<0:break
   path.append(cur)
  path=path[::-1]
  coords=np.stack([xx[path],yy[path]],1)
  # 15 px sample
  arr=[coords[0]];last=coords[0]
  for p in coords[1:]:
   if np.linalg.norm(p-last)>=20:arr.append(p);last=p
  if np.linalg.norm(coords[-1]-last)>1:arr.append(coords[-1])
  print('pathlen',len(coords),'samples',np.rint(arr).astype(int).tolist())

